), path_stats AS (
    SELECT
        archive_path,
        split_part(split_part(archive_path, '/COMPLETED/', 2), '/', 1) AS hpc_username,
        split_part(split_part(archive_path, '/COMPLETED/', 2), '/', 2) AS case_name,
        final_case_outcome,
        COUNT(*) FILTER (WHERE http_status = 409) AS http_409_failed_attempts,
        COUNT(*) FILTER (WHERE http_status = 500) AS http_500_failed_attempts,
        jsonb_agg(jsonb_build_object(
            'timestamp_utc', timestamp_utc,
            'attempt', attempt,
            'http_status', http_status
        ) ORDER BY timestamp_utc, attempt) AS failures
    FROM failed_requests
    GROUP BY archive_path, final_case_outcome
), case_stats AS (
    SELECT
        hpc_username,
        case_name,
        CASE
            WHEN SUM(http_409_failed_attempts) > 0 AND SUM(http_500_failed_attempts) > 0
                THEN 'both_http_409_and_500'
            WHEN SUM(http_409_failed_attempts) > 0 THEN 'http_409_only'
            ELSE 'http_500_only'
        END AS error_group,
        COUNT(*) AS affected_archive_paths,
        SUM(http_409_failed_attempts)::bigint AS http_409_failed_attempts,
        SUM(http_500_failed_attempts)::bigint AS http_500_failed_attempts,
        COUNT(*) FILTER (WHERE final_case_outcome = 'succeeded') AS case_paths_reported_succeeded,
        COUNT(*) FILTER (WHERE final_case_outcome = 'failed') AS case_paths_reported_failed,
        array_agg(archive_path ORDER BY archive_path) AS archive_paths,
        jsonb_agg(jsonb_build_object(
            'archive_path', archive_path,
            'final_case_outcome', final_case_outcome,
            'failed_attempts', failures
        ) ORDER BY archive_path) AS failure_details
    FROM path_stats
    GROUP BY hpc_username, case_name
), checked AS (
    SELECT
        f.*,
        'perlmutter'::text AS machine,
        d.execution_id AS expected_execution_id,
        c.id::text AS case_id,
        e.id::text AS execution_record_id,
        CASE
            WHEN m.id IS NULL THEN 'missing_machine'
            WHEN c.id IS NULL THEN 'missing_case'
            WHEN d.id IS NULL THEN 'no_accepted_discovery_record'
            WHEN e.id IS NULL THEN 'missing_execution'
            ELSE 'execution_exists'
        END AS database_status,
        CASE WHEN e.id IS NULL THEN NULL ELSE EXISTS (
            SELECT 1 FROM source_directories AS sd
            WHERE sd.execution_id = e.id AND sd.kind = 'archive'
        ) END AS has_archive_mapping
    FROM case_stats AS f
    LEFT JOIN machines AS m ON m.name = 'perlmutter'
    LEFT JOIN execution_discovery_results AS d
        ON d.machine_id = m.id
       AND d.case_identity = f.hpc_username || '/' || f.case_name
       AND d.outcome = 'accepted'
    LEFT JOIN cases AS c
        ON c.machine_id = m.id
       AND c.hpc_username = f.hpc_username
       AND c.name = f.case_name
    LEFT JOIN executions AS e
        ON e.case_id = c.id AND e.execution_id = d.execution_id
), report_groups (error_group) AS (
    VALUES ('all_http_errors'), ('http_409_only'), ('http_500_only'), ('both_http_409_and_500')
), request_summary AS (
    -- Aggregate BEFORE the execution join so request counts are not multiplied.
    SELECT
        g.error_group,
        COUNT(f.case_name) AS affected_cases,
        COALESCE(SUM(f.affected_archive_paths), 0)::bigint AS affected_archive_paths,
        COALESCE(SUM(f.http_409_failed_attempts), 0)::bigint AS http_409_failed_attempts,
        COALESCE(SUM(f.http_500_failed_attempts), 0)::bigint AS http_500_failed_attempts,
        COALESCE(SUM(f.case_paths_reported_succeeded), 0)::bigint AS case_paths_reported_succeeded,
        COALESCE(SUM(f.case_paths_reported_failed), 0)::bigint AS case_paths_reported_failed
    FROM report_groups AS g
    LEFT JOIN case_stats AS f
        ON g.error_group = 'all_http_errors' OR g.error_group = f.error_group
    GROUP BY g.error_group
), catalog_summary AS (
    SELECT
        g.error_group,
        COUNT(c.expected_execution_id) AS accepted_executions_checked,
        COUNT(c.execution_record_id) AS existing_executions,
        COUNT(*) FILTER (
            WHERE c.expected_execution_id IS NOT NULL AND c.execution_record_id IS NULL
        ) AS accepted_executions_without_catalog_match,
        COUNT(DISTINCT (c.hpc_username, c.case_name)) FILTER (
            WHERE c.database_status = 'missing_case'
        ) AS missing_cases,
        COUNT(*) FILTER (WHERE c.database_status = 'missing_execution') AS missing_executions_in_existing_cases,
        COUNT(*) FILTER (WHERE c.database_status = 'no_accepted_discovery_record') AS cases_without_accepted_discovery,
        COUNT(*) FILTER (
            WHERE c.execution_record_id IS NOT NULL AND NOT c.has_archive_mapping
        ) AS existing_executions_without_archive_mapping
    FROM report_groups AS g
    LEFT JOIN checked AS c
        ON g.error_group = 'all_http_errors' OR g.error_group = c.error_group
    GROUP BY g.error_group
)
SELECT
    r.error_group,
    'perlmutter'::text AS machine,
    EXISTS (SELECT 1 FROM machines WHERE name = 'perlmutter') AS machine_found,
    r.affected_cases,
    r.affected_archive_paths,
    r.http_409_failed_attempts,
    r.http_500_failed_attempts,
    r.case_paths_reported_succeeded,
    r.case_paths_reported_failed,
    c.accepted_executions_checked,
    c.existing_executions,
    c.accepted_executions_without_catalog_match,
    c.missing_cases,
    c.missing_executions_in_existing_cases,
    c.cases_without_accepted_discovery,
    c.existing_executions_without_archive_mapping
FROM request_summary AS r
JOIN catalog_summary AS c USING (error_group)
ORDER BY CASE r.error_group
    WHEN 'all_http_errors' THEN 0
    WHEN 'http_409_only' THEN 1
    WHEN 'http_500_only' THEN 2
    ELSE 3
END;

